def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5, -2, 7, 3]), fmt([100, -100]), fmt([4]), fmt([0]), fmt([-100]), fmt([1, 1]), fmt([-100, 100, -100]),
             fmt([100, 100, 100, 100, 100])]
    for n in (2, 3, 5, 8, 11, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-100, 100) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-100, 100) for _ in range(N)]))
    tests.append(fmt([100] * N))
    tests.append(fmt([-100 if i % 2 == 0 else 100 for i in range(N)]))
    tests.append(fmt([100 if i % 2 == 0 else -100 for i in range(N)]))
    tests.append(fmt([rng.randint(-100, 100) for _ in range(N - 1)]))
    return tests

